  return `<div class="validation-ledger" id="validation-detection"><header><span>ACTIVE-FIRE DETECTION · INDEPENDENT FROZEN AREA×TIME</span><strong>${metrics.eligibleCases??0} eligible windows · ${metrics.positiveCases??0} positive / ${metrics.negativeCases??0} negative</strong><p>${escapeHtml(benchmark.headline?.qualification??'Detection benchmark unavailable.')}</p></header><div class="heldout-metrics"><div><span>TRUE POSITIVES</span><strong>${metrics.truePositives??'UNMEASURED'}</strong></div><div><span>FALSE POSITIVES</span><strong>${metrics.falsePositives??'UNMEASURED'}</strong></div><div><span>TRUE NEGATIVES</span><strong>${metrics.trueNegatives??'UNMEASURED'}</strong></div><div><span>FALSE NEGATIVES</span><strong>${metrics.falseNegatives??'UNMEASURED'}</strong></div><div><span>PRECISION · CONDITIONAL</span><strong>${pct(metrics.precision)}</strong></div><div><span>RECALL · GIVEN SIGNAL</span><strong>${pct(metrics.recall)}</strong></div><div><span>F1</span><strong>${pct(metrics.f1)}</strong></div><div><span>SPECIFICITY</span><strong>${pct(metrics.specificity)}</strong></div><div><span>FALSE-POSITIVE RATE</span><strong>${pct(metrics.falsePositiveRate)}</strong></div><div><span>BALANCED ACCURACY</span><strong>${pct(metrics.balancedAccuracy)}</strong></div><div><span>MCC</span><strong>${metrics.matthewsCorrelationCoefficient??'UNMEASURED'}</strong></div><div><span>ABSTENTION</span><strong>${pct(metrics.abstentionRate)}</strong></div></div><section class="validation-corpus"><span>AREA×TIME CORPUS · CLASS COUNTS VISIBLE</span><strong>${inventory.windows??0} windows · ${inventory.labelled??0} labelled · ${inventory.unlabelled??0} unlabelled</strong><p>${inventory.positive??0} official-fire windows, ${inventory.negative??0} static/offshore hard-negative windows. Only ${metrics.eligibleCases??0} frozen confirmatory windows have both a resolved label and proven observation opportunity. Unlabelled windows remain unscored.</p></section><section class="validation-corpus"><span>SMALL / LOW-SIGNAL · CONDITIONAL</span><strong>${small.acceptedByVigia??0}/${small.validObservationOpportunity??0} accepted · ${small.totalKnownFires??0} total known</strong><p>${small.noOpportunity??0} have no proven opportunity. Policy recall given a retained provider signal ${pct(small.policyRecallGivenProviderSignal)}; unconditional matched-signal coverage ${pct(small.unconditionalCoverage)}. Sensor recall is unmeasured.</p></section><section class="validation-corpus"><span>V1 → V2 · FROZEN CONFIRMATORY</span><strong>Specificity ${pct(metrics.specificity)} → ${pct(v2.specificity)} · FPR ${pct(metrics.falsePositiveRate)} → ${pct(v2.falsePositiveRate)}</strong><p>Balanced accuracy ${pct(metrics.balancedAccuracy)} → ${pct(v2.balancedAccuracy)} · MCC ${metrics.matthewsCorrelationCoefficient??'—'} → ${v2.matthewsCorrelationCoefficient??'—'} · recall delta ${pct(delta.recall)}. ${escapeHtml(benchmark.v2Candidate?.promotionDecision??'Promotion not evaluated')}.</p></section><section class="validation-corpus"><span>ERROR EXPLORER · ${errors.length} FROZEN AREA×TIME V1 ERRORS</span>${errorRows(errors,'No scored confirmatory errors. This never implies zero landscape errors.')}</section><section class="validation-corpus"><span>LEGACY HELD-OUT ERROR REGRESSION · ${legacyErrors.length} / ${benchmark.regressionReference?.headline?.metrics?.falsePositives+benchmark.regressionReference?.headline?.metrics?.falseNegatives||0}</span><p>${escapeHtml(benchmark.regressionReference?.qualification??'Legacy benchmark unavailable.')}</p>${errorRows(legacyErrors,'No retained legacy errors.')}</section></div>`;
