  if(!sorted.length)return `${lifecycleStrip}${measurement}<p class="queue-empty">No persisted operational alerts are open at this governed clock.</p>`;
  const records=sorted.slice(0,80).map((alert)=>{const lifecycle=alert.lifecycleState??(alert.acknowledgedAt?'ACKNOWLEDGED':'OPEN'),visibleState=uiState(alert),prevention=alert.subjectType==='PREVENTION_REVIEW_QUEUE'||alert.alertType==='PREVENTION_REVIEW_DUE',title=prevention?`${alert.payload?.dueCount??''} PREVENT measurement / validation items due`.trim():(alert.title??statusLabel(alert.type??alert.policyId??'Operational alert')),reason=prevention?'Physical-change evidence requires a governed measurement plan or external validation gate; unstable geometry is not an intervention-review candidate.':(alert.reason??alert.reasonCode??alert.payload?.reason??alert.payload?.decisionReason??'Evidence state changed under the governed alert policy.'),canAcknowledge=!alert.acknowledgedAt&&!['RESOLVED','SUPPRESSED'].includes(lifecycle),canAssign=['ACKNOWLEDGED','ESCALATED'].includes(lifecycle)&&alert.ownerActorId!==actor?.id,detectedAt=alert.payload?.physicalLastAt,alertedAt=alert.openedAt??alert.createdAt,owner=alert.ownerActorId===actor?.id?actor.name:alert.ownerActorId?'Assigned operator':'Unassigned';return`<article class="status-card alert-record state-${escapeHtml(visibleState.toLowerCase())}"><header><div><span>${escapeHtml(visibleState)}</span><strong>${escapeHtml(title)}</strong></div><b>${escapeHtml(statusLabel(alert.priority??'unranked'))}</b></header><p>${escapeHtml(reason)}</p><dl><div><dt>Event</dt><dd>${escapeHtml(alert.eventId??alert.subjectId??'Non-event operational subject')}</dd></div><div><dt>Detected</dt><dd>${detectedAt?escapeHtml(new Date(detectedAt).toLocaleString()):'Not applicable / unavailable'}</dd></div><div><dt>Alerted</dt><dd>${alertedAt?escapeHtml(new Date(alertedAt).toLocaleString()):'Time unavailable'}</dd></div><div><dt>Acknowledgement</dt><dd>${alert.acknowledgedAt?escapeHtml(new Date(alert.acknowledgedAt).toLocaleString()):'Pending'}</dd></div><div><dt>Owner</dt><dd>${escapeHtml(owner)}</dd></div><div><dt>Policy</dt><dd>${escapeHtml(alert.policyId??'Unavailable')}</dd></div></dl><div class="action-grid">${canAcknowledge?`<button type="button" class="secondary-action" data-action="ack-alert" data-id="${escapeHtml(alert.id)}">Acknowledge</button>`:''}${canAssign?`<button type="button" class="secondary-action" data-action="assign-alert" data-id="${escapeHtml(alert.id)}">Take ownership</button>`:''}${alert.eventId?`<button type="button" class="secondary-action" data-select-kind="event" data-select-id="${escapeHtml(alert.eventId)}">Open incident</button>`:''}</div></article>`;}).join('');
  return`${lifecycleStrip}${measurement}<div class="alert-record-list">${records}</div>`;
